def boxes(grid):
    H,W=len(grid),len(grid[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for i in range(H):
        for j in range(W):
            if grid[i][j]==2 and not seen[i][j]:
                stack=[(i,j)]; seen[i][j]=True; cells=[]
                while stack:
                    y,x=stack.pop(); cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and grid[ny][nx]==2 and not seen[ny][nx]:
                            seen[ny][nx]=True; stack.append((ny,nx))
                ys=[c[0] for c in cells]; xs=[c[1] for c in cells]
                out.append((min(ys),max(ys),min(xs),max(xs)))
    return out
def transform(grid):
    g=[row[:] for row in grid]
    for t0,b,l,r in boxes(grid):
        area=(b-t0-1)*(r-l-1)
